package cli

import (
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/spf13/cobra"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// newLeafCmd builds a subcommand that does nothing, for tests that care about
// how the tree is wired rather than about what a command does.
func newLeafCmd(use string) *cobra.Command {
	return &cobra.Command{
		Use:   use,
		Short: "a subcommand used only by the wiring tests",
		Args:  cobra.NoArgs,
		RunE:  func(*cobra.Command, []string) error { return nil },
	}
}

// TestRootDeclaresNoPersistentFlags guards the rule that gives --json its
// meaning: nothing is inherited, so a flag a command accepts is a flag that
// command honours. A persistent flag added here — however convenient — would be
// accepted by every future verb whether or not it did anything with it.
func TestRootDeclaresNoPersistentFlags(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	// Cobra registers --help and --version lazily, and on Flags() rather than
	// PersistentFlags(); force that to happen so the assertion is made against
	// a fully initialized command rather than an empty one.
	root.InitDefaultHelpFlag()
	root.InitDefaultVersionFlag()

	assert.False(t, root.PersistentFlags().HasFlags(),
		"the root must declare no persistent flags; register a flag locally on each command that honours it:\n%s",
		root.PersistentFlags().FlagUsages())

	child := newLeafCmd("leaf")
	addCommand(root, child, groupSetup)
	assert.False(t, child.InheritedFlags().HasFlags(),
		"a subcommand must inherit nothing from the root:\n%s", child.InheritedFlags().FlagUsages())
}

// TestJSONFlagIsUnknownOnACommandThatDoesNotDeclareIt is the same rule observed
// from the outside: --json is accepted where it is registered and fails loudly
// everywhere else, rather than being accepted and ignored.
func TestJSONFlagIsUnknownOnACommandThatDoesNotDeclareIt(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		args    []string
		wantErr string
	}{
		{"the command that declares it accepts it", []string{"renders", "--json"}, ""},
		{"a sibling that does not declare it rejects it", []string{"acts", "--json"}, "unknown flag: --json"},
		{"the root rejects it too", []string{"--json"}, "unknown flag: --json"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			root := NewRootCmd()
			renders := newLeafCmd("renders")
			addJSONFlag(renders)
			addCommand(root, newLeafCmd("acts"), groupSetup)
			addCommand(root, renders, groupAssets)
			root.SetArgs(tc.args)
			root.SetOut(&strings.Builder{})
			root.SetErr(&strings.Builder{})

			err := root.Execute()

			if tc.wantErr == "" {
				require.NoError(t, err)
				assert.True(t, jsonRequested(renders), "the flag the command declared must read back as requested")
				return
			}
			require.Error(t, err)
			assert.Contains(t, err.Error(), tc.wantErr)
		})
	}
}

// TestJSONRequestedTreatsAnUndeclaredFlagAsNotRequested pins the read helper's
// contract: asking a command that has no JSON view is a truthful no, not a
// panic, so shared rendering helpers can ask unconditionally.
func TestJSONRequestedTreatsAnUndeclaredFlagAsNotRequested(t *testing.T) {
	t.Parallel()

	declared := newLeafCmd("declared")
	addJSONFlag(declared)
	require.False(t, jsonRequested(declared), "an unset --json is not a request")
	require.NoError(t, declared.Flags().Set("json", "true"))
	assert.True(t, jsonRequested(declared), "a set --json is a request")

	assert.False(t, jsonRequested(newLeafCmd("undeclared")),
		"a command with no --json flag must answer no rather than panicking")
}

// TestHelpGroupsAreDeclaredInDisplayOrder holds the coupling addCommand relies
// on: a group is declared the first time a command uses it, so attaching
// commands out of helpGroups order would silently reorder the help output.
func TestHelpGroupsAreDeclaredInDisplayOrder(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	addCommand(root, newLeafCmd("setup-verb"), groupSetup)
	addCommand(root, newLeafCmd("asset-verb"), groupAssets)
	addCommand(root, newLeafCmd("another-asset-verb"), groupAssets)

	got := make([]string, 0, len(root.Groups()))
	for _, g := range root.Groups() {
		got = append(got, g.ID)
	}
	assert.Equal(t, []string{groupSetup, groupAssets}, got,
		"each group is declared once, on first use, in the order commands are attached")

	usage := root.UsageString()
	assert.Less(t, strings.Index(usage, "Setup Commands:"), strings.Index(usage, "Asset Commands:"))
}

// TestNewRootCmdDeclaresNoEmptyHelpGroup keeps the help output honest while the
// command set is still being built: cobra prints a header for every declared
// group, so a group whose commands do not exist yet must stay undeclared rather
// than render as an empty heading.
func TestNewRootCmdDeclaresNoEmptyHelpGroup(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	for _, g := range root.Groups() {
		assert.True(t, groupHasMember(root, g.ID), "help group %q is declared but no command is filed under it", g.ID)
	}
}

func groupHasMember(root *cobra.Command, groupID string) bool {
	for _, c := range root.Commands() {
		if c.GroupID == groupID {
			return true
		}
	}
	return false
}

// TestEveryCommandIsFiledUnderADeclaredGroup checks at construction time the
// invariant cobra only panics over at execute time.
func TestEveryCommandIsFiledUnderADeclaredGroup(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	for _, c := range root.Commands() {
		if c.GroupID == "" {
			continue // cobra's own generated help and completion commands
		}
		assert.True(t, root.ContainsGroup(c.GroupID), "command %q is filed under undeclared group %q", c.Name(), c.GroupID)
	}
}

func TestAddCommandRejectsAnUnknownHelpGroup(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	assert.PanicsWithValue(t, `command "stray" filed under unknown help group "nowhere"`, func() {
		addCommand(root, newLeafCmd("stray"), "nowhere")
	})
}

// TestPackageDeclaresNoInit asserts by construction that no command registers
// itself from a package init, so NewRootCmd is the whole tree and reading it is
// enough to know what harnaas accepts. The gochecknoinits linter says the same,
// but a lint rule can be silenced by a comment and this cannot.
func TestPackageDeclaresNoInit(t *testing.T) {
	t.Parallel()

	entries, err := os.ReadDir(".")
	require.NoError(t, err)

	fset := token.NewFileSet()
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		file, err := parser.ParseFile(fset, filepath.Join(".", name), nil, parser.SkipObjectResolution)
		require.NoError(t, err)

		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Recv != nil {
				continue
			}
			assert.NotEqual(t, "init", fn.Name.Name,
				"%s declares a package init; attach commands from NewRootCmd instead", name)
		}
	}
}

package cli

import (
	"bytes"
	"encoding/json"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestPrintJSONWritesOneDocumentToStdoutAlone is the property that makes
// `harnaas … --json | jq` safe: the document is the only thing on stdout, and
// the advisory text a command emits alongside it lands on stderr.
func TestPrintJSONWritesOneDocumentToStdoutAlone(t *testing.T) {
	t.Parallel()

	cmd := newLeafCmd("renders")
	var out, errOut bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(&errOut)

	advisef(cmd, "Resolving %d assets…\n", 2)
	require.NoError(t, printJSON(cmd, map[string]any{"installed": 2}))
	advisef(cmd, "Done.\n")

	var doc map[string]any
	require.NoError(t, json.Unmarshal(out.Bytes(), &doc),
		"stdout must parse as a single JSON document, got %q", out.String())
	assert.Equal(t, map[string]any{"installed": float64(2)}, doc)
	assert.Equal(t, "Resolving 2 assets…\nDone.\n", errOut.String())
}

// TestPrintJSONLeavesHTMLUnescaped guards the encoder setting: Go escapes <, >
// and & by default, which would rewrite an asset id, a path or a source ref
// into something no consumer asked for.
func TestPrintJSONLeavesHTMLUnescaped(t *testing.T) {
	t.Parallel()

	cmd := newLeafCmd("renders")
	var out bytes.Buffer
	cmd.SetOut(&out)

	require.NoError(t, printJSON(cmd, map[string]string{"source": "github:acme/assets?ref=a&tag=b"}))

	// htmlEscapedAmpersand is what Go's default encoder would have written.
	const htmlEscapedAmpersand = "\\u0026"

	assert.Contains(t, out.String(), "a&tag=b")
	assert.NotContains(t, out.String(), htmlEscapedAmpersand,
		"the ampersand must survive verbatim, not as Go's default HTML escape")
}

// TestPrintJSONEndsWithExactlyOneNewline keeps the document a clean unit for a
// line-oriented reader.
func TestPrintJSONEndsWithExactlyOneNewline(t *testing.T) {
	t.Parallel()

	cmd := newLeafCmd("renders")
	var out bytes.Buffer
	cmd.SetOut(&out)

	require.NoError(t, printJSON(cmd, []string{"skills/review"}))

	assert.Equal(t, "[\n  \"skills/review\"\n]\n", out.String())
}

// TestPrintJSONReportsAnEncodingFailure proves an unencodable value surfaces as
// an error the entrypoint can render, rather than as silently truncated stdout.
func TestPrintJSONReportsAnEncodingFailure(t *testing.T) {
	t.Parallel()

	cmd := newLeafCmd("renders")
	cmd.SetOut(&bytes.Buffer{})

	err := printJSON(cmd, func() {})

	require.Error(t, err)
	assert.Contains(t, err.Error(), "encode json output")
}

// Package logging writes harnaas's diagnostics to a file, and never to the
// terminal.
//
// # Why a file, and only a file
//
// The terminal belongs to the command's own output. A diagnostic on stdout
// would corrupt a --json document mid-parse; one on stderr would interleave
// with the advisory text a user is trying to read. So records go to a log file
// under the user's cache directory, and where that file cannot be opened they
// are discarded rather than falling back to a stream — a fallback that turns a
// disk problem into a parse failure is worse than no logging at all.
//
// The file lives outside the project on purpose. harnaas is a tool that writes
// into repositories, and a log directory appearing in a team's working tree
// after a read-only command would be a side effect nobody asked for.
//
// # What must never be logged
//
// Identifiers, paths, durations, counts and outcomes may be logged. File
// contents, instruction or rule text, captured output and credentials may not.
//
// This rule is sharper for harnaas than for most tools. The files it handles are
// a team's instructions and rules — the prose they write for their own AI
// harnesses — and that is exactly the content nobody expects to find copied into
// a log they did not know existed. "The file failed to parse" is a diagnostic;
// the line that failed to parse is user content.
//
// The API is attribute-only for the same reason: every logged value arrives as a
// named field, so reviewing what harnaas records is reviewing a list of keys
// rather than reading through interpolated message strings.
package logging

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

// Environment variables read by this package. There is no configuration
// library and no manifest key for either: logging has to work before anything
// is loaded, and both of these are things a person sets for one run while
// working out what harnaas did.
const (
	// LevelEnvVar sets the minimum level recorded: debug, info, warn or error.
	// Unset or unrecognized means info.
	LevelEnvVar = "HARNAAS_LOG_LEVEL"

	// FileEnvVar overrides the log file path outright. It takes precedence over
	// the per-user default; an unset value means the default.
	FileEnvVar = "HARNAAS_LOG_FILE"
)

// dirName and fileName spell the default location under the user's cache
// directory: <cache>/harnaas/logs/harnaas.log.
const (
	dirName  = "harnaas"
	logsDir  = "logs"
	fileName = "harnaas.log"
)

var (
	// mu guards logger and file. It is held across a write so a concurrent
	// close cannot pull the file out from under one.
	mu sync.RWMutex

	// logger is where records go. It starts discarding, and goes back to
	// discarding whenever the file cannot be opened, so a log call is always
	// safe and never reaches a terminal.
	logger = discarding()

	// file is the open log file, if any.
	file *os.File
)

// discarding returns a logger that drops every record. It is a real logger
// rather than a nil check at each call site so the "not opened yet" path and
// the "could not open" path behave identically — and it is emphatically not
// slog.Default(), which writes to stderr.
func discarding() *slog.Logger {
	return slog.New(slog.DiscardHandler)
}

// Open directs records to harnaas's log file and returns the function that
// closes it. Call it once, from the entrypoint, and defer the result.
//
// It reports nothing on failure and returns no error, because there is nowhere
// to report to: the terminal is the command's, and a warning printed there is
// the exact interleaving this package exists to prevent. A run whose log file
// could not be opened simply produces no log.
func Open() func() {
	if err := open(resolveFile()); err != nil {
		Close()
	}
	return Close
}

// open points the package logger at path, creating the containing directory and
// appending to any log already there. It is separated from Open so tests can
// see the failure Open deliberately swallows.
func open(path string) error {
	Close()

	if path == "" {
		return fmt.Errorf("no log file location: set %s to choose one", FileEnvVar)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return fmt.Errorf("create the log directory %s: %w", filepath.Dir(path), err)
	}

	// 0600: the log records which projects this user ran harnaas against, which
	// is nobody else's business on a shared machine.
	//nolint:gosec // G304: the path is harnaas's own log location, or the one the user named in HARNAAS_LOG_FILE for their own run.
	f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
	if err != nil {
		return fmt.Errorf("open the log file %s: %w", path, err)
	}

	mu.Lock()
	defer mu.Unlock()
	file = f
	// Unbuffered: harnaas writes a handful of records per run, so there is
	// nothing to gain by batching them, and a buffer loses exactly the records
	// that matter when a run dies unexpectedly.
	logger = slog.New(slog.NewJSONHandler(f, &slog.HandlerOptions{Level: level()}))
	return nil
}

// Close flushes and closes the log file, and sends subsequent records back to
// the discarding logger. It is safe to call more than once.
func Close() {
	mu.Lock()
	defer mu.Unlock()

	logger = discarding()
	if file != nil {
		_ = file.Close()
		file = nil
	}
}

// resolveFile returns the log file path. Precedence, documented here at its
// only read site: HARNAAS_LOG_FILE, then <user cache dir>/harnaas/logs. An
// empty result means neither is available, and open turns that into the error
// it reports to nobody.
func resolveFile() string {
	if override := strings.TrimSpace(os.Getenv(FileEnvVar)); override != "" {
		return override
	}

	cache, err := os.UserCacheDir()
	if err != nil {
		return ""
	}
	return filepath.Join(cache, dirName, logsDir, fileName)
}

// level returns the minimum level to record. Precedence, documented here at its
// only read site: HARNAAS_LOG_LEVEL, then info. An unrecognized value is info
// too — refusing to run because a debugging aid was misspelled would be a poor
// trade — and the misspelling is itself recorded once the logger is up.
func level() slog.Level {
	switch strings.ToLower(strings.TrimSpace(os.Getenv(LevelEnvVar))) {
	case "debug":
		return slog.LevelDebug
	case "info", "":
		return slog.LevelInfo
	case "warn", "warning":
		return slog.LevelWarn
	case "error":
		return slog.LevelError
	default:
		return slog.LevelInfo
	}
}

// Debug records developer-facing detail: what harnaas considered and skipped.
func Debug(ctx context.Context, msg string, attrs ...slog.Attr) {
	record(ctx, slog.LevelDebug, msg, attrs)
}

// Info records the outcome of a step a user would recognize.
func Info(ctx context.Context, msg string, attrs ...slog.Attr) {
	record(ctx, slog.LevelInfo, msg, attrs)
}

// Warn records something harnaas worked around and would rather the user knew
// about. The user-facing half of that belongs on stderr; this is the record of
// it.
func Warn(ctx context.Context, msg string, attrs ...slog.Attr) {
	record(ctx, slog.LevelWarn, msg, attrs)
}

// Error records a failure. The user-facing explanation is the entrypoint's job;
// this is what a maintainer reads afterwards.
func Error(ctx context.Context, msg string, attrs ...slog.Attr) {
	record(ctx, slog.LevelError, msg, attrs)
}

// record writes one entry, prefixing the attributes carried by ctx so component
// and command sort ahead of the call site's own fields.
//
// The read lock spans the write: Close must not be able to swap the logger
// halfway through one.
func record(ctx context.Context, lvl slog.Level, msg string, attrs []slog.Attr) {
	mu.RLock()
	defer mu.RUnlock()

	logger.LogAttrs(ctx, lvl, msg, append(contextAttrs(ctx), attrs...)...)
}

package logging

import (
	"bytes"
	"encoding/json"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

// logTo points the package at a fresh log file under t.TempDir and returns its
// path. Every test that logs goes through it, so no test can touch the real
// per-user log.
func logTo(t *testing.T) string {
	t.Helper()

	path := filepath.Join(t.TempDir(), "harnaas.log")
	t.Setenv(FileEnvVar, path)
	require.NoError(t, open(resolveFile()))
	t.Cleanup(Close)
	return path
}

// records reads the log file back as one map per record.
func records(t *testing.T, path string) []map[string]any {
	t.Helper()

	raw, err := os.ReadFile(path)
	require.NoError(t, err)

	var out []map[string]any
	for line := range strings.Lines(strings.TrimSpace(string(raw))) {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		var rec map[string]any
		require.NoError(t, json.Unmarshal([]byte(line), &rec), "log line is not JSON: %s", line)
		out = append(out, rec)
	}
	return out
}

// silenceDefault redirects the process streams and slog's default logger into
// buffers, and asserts on cleanup that nothing reached any of them. It is how
// "logging never touches the terminal" is checked rather than assumed: the
// tempting fallback — writing to stderr when the log file cannot be opened — is
// exactly what would corrupt a --json document.
func silenceDefault(t *testing.T) {
	t.Helper()

	stdout, stderr := redirect(t, &os.Stdout), redirect(t, &os.Stderr)

	var fallback bytes.Buffer
	previous := slog.Default()
	slog.SetDefault(slog.New(slog.NewJSONHandler(&fallback, nil)))

	t.Cleanup(func() {
		slog.SetDefault(previous)

		require.Empty(t, read(t, stdout), "logging wrote to stdout")
		require.Empty(t, read(t, stderr), "logging wrote to stderr")
		require.Empty(t, fallback.String(), "logging fell back to slog's default logger")
	})
}

// redirect replaces a process stream with a file under t.TempDir and returns its
// path, restoring the original on cleanup.
func redirect(t *testing.T, stream **os.File) string {
	t.Helper()

	path := filepath.Join(t.TempDir(), "stream")
	f, err := os.Create(path)
	require.NoError(t, err)

	previous := *stream
	*stream = f
	t.Cleanup(func() {
		*stream = previous
		require.NoError(t, f.Close())
	})
	return path
}

func read(t *testing.T, path string) string {
	t.Helper()

	raw, err := os.ReadFile(path)
	require.NoError(t, err)
	return string(raw)
}

func TestRecordsGoToTheLogFileAndNowhereElse(t *testing.T) {
	silenceDefault(t)
	path := logTo(t)

	Info(t.Context(), "manifest loaded", slog.Int("assets", 3))

	got := records(t, path)
	require.Len(t, got, 1)
	require.Equal(t, "manifest loaded", got[0]["msg"])
	require.Equal(t, "INFO", got[0]["level"])
	require.InDelta(t, 3.0, got[0]["assets"], 0)
	require.Contains(t, got[0], "time")
}

func TestUnopenedLoggingDiscardsInsteadOfPrinting(t *testing.T) {
	silenceDefault(t)
	Close() // the state a binary is in before Open runs, and after it fails

	Info(t.Context(), "before the log file exists", slog.String("path", "harnaas.json"))
	Error(t.Context(), "and after it is closed again")
	// silenceDefault's cleanup asserts the streams stayed empty.
}

func TestContextLabelsEveryRecordWithCommandAndComponent(t *testing.T) {
	silenceDefault(t)
	path := logTo(t)

	ctx := WithComponent(WithCommand(t.Context(), "install"), "manifest")
	Warn(ctx, "source ref is a moving target", slog.String("source", "acme"))

	got := records(t, path)
	require.Len(t, got, 1)
	require.Equal(t, "install", got[0][CommandKey])
	require.Equal(t, "manifest", got[0][ComponentKey])
	require.Equal(t, "acme", got[0]["source"])
}

func TestAnInnerComponentReplacesTheOuterOneForItsOwnRecords(t *testing.T) {
	silenceDefault(t)
	path := logTo(t)

	outer := WithComponent(t.Context(), "install")
	inner := WithComponent(outer, "manifest")

	Info(inner, "inner")
	Info(outer, "outer")

	got := records(t, path)
	require.Len(t, got, 2)
	require.Equal(t, "manifest", got[0][ComponentKey])
	require.Equal(t, "install", got[1][ComponentKey], "the inner label does not leak back out")
}

func TestLevelFiltersRecordsBelowTheConfiguredThreshold(t *testing.T) {
	silenceDefault(t)
	t.Setenv(LevelEnvVar, "warn")
	path := logTo(t)

	Debug(t.Context(), "debug")
	Info(t.Context(), "info")
	Warn(t.Context(), "warn")
	Error(t.Context(), "error")

	got := records(t, path)
	require.Len(t, got, 2)
	require.Equal(t, "warn", got[0]["msg"])
	require.Equal(t, "error", got[1]["msg"])
}

func TestLevelDefaultsToInfoForEveryUnusableValue(t *testing.T) {
	for _, value := range []string{"", "   ", "verbose", "TRACE", "42"} {
		t.Run("level="+value, func(t *testing.T) {
			t.Setenv(LevelEnvVar, value)
			require.Equal(t, slog.LevelInfo, level(),
				"a misspelled debugging aid must not change what harnaas records")
		})
	}
}

func TestLevelAcceptsItsNamesCaseInsensitively(t *testing.T) {
	cases := []struct {
		value string
		want  slog.Level
	}{
		{value: "debug", want: slog.LevelDebug},
		{value: "DEBUG", want: slog.LevelDebug},
		{value: " Info ", want: slog.LevelInfo},
		{value: "warn", want: slog.LevelWarn},
		{value: "WARNING", want: slog.LevelWarn},
		{value: "Error", want: slog.LevelError},
	}

	for _, tc := range cases {
		t.Run("level="+tc.value, func(t *testing.T) {
			t.Setenv(LevelEnvVar, tc.value)
			require.Equal(t, tc.want, level())
		})
	}
}

func TestRecordsAppendToAnExistingLogRatherThanReplacingIt(t *testing.T) {
	silenceDefault(t)
	path := logTo(t)

	Info(t.Context(), "first run")
	Close()

	require.NoError(t, open(resolveFile()))
	Info(t.Context(), "second run")

	got := records(t, path)
	require.Len(t, got, 2, "a later run must not erase the run that produced the problem")
	require.Equal(t, "first run", got[0]["msg"])
	require.Equal(t, "second run", got[1]["msg"])
}

func TestTheDefaultLocationIsOutsideTheProject(t *testing.T) {
	t.Setenv(FileEnvVar, "")

	cache, err := os.UserCacheDir()
	require.NoError(t, err)

	// The project tree stays untouched by a read-only command, so the log lives
	// under the user's cache directory, not under the repository.
	require.Equal(t, filepath.Join(cache, dirName, logsDir, fileName), resolveFile())
}

func TestTheFileOverrideWins(t *testing.T) {
	chosen := filepath.Join(t.TempDir(), "elsewhere.log")
	t.Setenv(FileEnvVar, chosen)

	require.Equal(t, chosen, resolveFile())
}

func TestAnUnopenableLogFileLeavesTheCommandRunnable(t *testing.T) {
	silenceDefault(t)

	// A regular file where the log directory should be: MkdirAll fails on every
	// platform, which is the closest stand-in for a full or read-only disk.
	blocker := filepath.Join(t.TempDir(), "blocker")
	require.NoError(t, os.WriteFile(blocker, nil, 0o600))
	t.Setenv(FileEnvVar, filepath.Join(blocker, "logs", "harnaas.log"))

	require.Error(t, open(resolveFile()), "the failure is visible to this package")

	closeLog := Open()
	defer closeLog()

	// Open reports nothing, and the run continues with logging simply absent.
	Info(t.Context(), "the command keeps working", slog.String("path", "harnaas.json"))
}

func TestCloseIsSafeToCallRepeatedly(t *testing.T) {
	silenceDefault(t)
	logTo(t)

	Info(t.Context(), "recorded")
	Close()
	Close()

	Info(t.Context(), "discarded")
}

package cli

import (
	"fmt"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/versioninfo"
	"github.com/spf13/cobra"
)

const rootLong = `harnaas manages a project's AI-harness assets as a declared, versioned
dependency: harnaas.json declares them, harnaas install places them, and
harnaas lint verifies them.`

// The help group ids. A group exists to answer "where do I start?" before
// "what else is there?", which is why setup comes first.
const (
	groupSetup  = "setup"
	groupAssets = "assets"
)

// helpGroups declares every help group in display order: getting a project
// declared, then the verbs that act on what it declares. addCommand declares a
// group on the root the first time a command files itself under it, so the
// order commands are attached in NewRootCmd must follow this list — cobra
// renders group headers in declaration order, and it prints a header for a
// declared group whether or not the group has any members.
var helpGroups = []cobra.Group{
	{ID: groupSetup, Title: "Setup Commands:"},
	{ID: groupAssets, Title: "Asset Commands:"},
}

// NewRootCmd builds the harnaas command tree.
//
// Cobra's own error and usage printing is silenced here so the process
// entrypoint is the only component that renders an error or chooses an exit
// code. The root deliberately declares no persistent flags: a flag that applies
// to some commands is registered locally on each command that honours it, so
// accepting a flag and honouring it are the same act.
//
// Subcommands are attached by explicit constructor calls from this function.
// Nothing registers itself from a package init, so the tree is readable in one
// place.
func NewRootCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "harnaas",
		Short: "Manage a project's AI-harness assets as a versioned dependency",
		Long:  rootLong,
		// Version must be read after versioninfo.Load(), which the entrypoint
		// calls before building the tree.
		Version:       versioninfo.Version,
		SilenceErrors: true,
		SilenceUsage:  true,
		// The root itself takes no positional arguments, so an unrecognized
		// verb is reported as an unknown command rather than swallowed. Cobra
		// only infers that once subcommands exist; stating it keeps the
		// behaviour true of an empty tree too.
		Args: cobra.NoArgs,
		// The generated completion command stays functional but out of help.
		CompletionOptions: cobra.CompletionOptions{HiddenDefaultCmd: true},
		RunE: func(cmd *cobra.Command, _ []string) error {
			if err := cmd.Help(); err != nil {
				return fmt.Errorf("render help: %w", err)
			}
			return nil
		},
	}

	cmd.SetVersionTemplate(fmt.Sprintf("harnaas %s (%s)\n", versioninfo.Version, versioninfo.Commit))

	// Every subcommand is attached here, by an explicit constructor call, in
	// helpGroups order. Nothing registers itself from a package init — the
	// gochecknoinits linter forbids one, and TestPackageDeclaresNoInit asserts
	// it over the sources — so this function is the entire command tree, and
	// reading it is enough to know what harnaas accepts.
	//
	// The commented lines are the commands their own changes attach here, kept
	// in place so the order stays visible: a group's header is rendered where
	// its first command was attached, so install and lint must land after init.
	addCommand(cmd, newInitCmd(), groupSetup)
	//	addCommand(cmd, newInstallCmd(), groupAssets)  // add-harnaas-install
	//	addCommand(cmd, newLintCmd(), groupAssets)     // add-harnaas-lint

	return cmd
}

// addCommand attaches child to parent under the named help group, declaring
// the group on parent the first time a command uses it. It is the only way a
// command joins the tree.
//
// An unknown group id is a wiring mistake in this file, not a runtime
// condition, and cobra itself panics at execute time for a command filed under
// an undeclared group. Panicking here instead surfaces the typo at the point
// that made it, naming both the command and the group.
func addCommand(parent, child *cobra.Command, groupID string) {
	title, ok := helpGroupTitle(groupID)
	if !ok {
		panic(fmt.Sprintf("command %q filed under unknown help group %q", child.Name(), groupID))
	}
	if !parent.ContainsGroup(groupID) {
		parent.AddGroup(&cobra.Group{ID: groupID, Title: title})
	}
	child.GroupID = groupID
	parent.AddCommand(child)
}

// helpGroupTitle returns the display title declared for a help group id.
func helpGroupTitle(id string) (string, bool) {
	for _, g := range helpGroups {
		if g.ID == id {
			return g.Title, true
		}
	}
	return "", false
}

// Command harnaas manages a project's AI-harness assets as a declared,
// versioned dependency of the repository.
//
// This file owns the whole process contract: it is the only component that
// prints an error, the only one that chooses an exit code, and the only one
// that decides how a signal terminates the process. Commands return errors;
// what those errors look like on the terminal is decided here, once.
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/signal"
	"runtime"
	"strings"
	"syscall"
	"time"

	"github.com/harnaas/harnaas/cmd/harnaas/cli"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/logging"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/paths"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/versioninfo"
	"github.com/harnaas/harnaas/internal/procsignal"
	"github.com/spf13/cobra"
)

// The exit-code contract. Every status harnaas can produce is listed here, and
// a new one must not be introduced without a documented meaning.
//
//   - exitSuccess       the command completed and found nothing to report.
//   - exitFailure       any runtime failure: bad configuration, I/O, network.
//   - exitLintFindings  reserved: `lint` ran its checks to completion and
//     reported at least one error-severity finding.
//
// exitLintFindings exists so a CI job can tell "lint crashed" from "lint worked
// and your harness has drifted" — the distinction lint exists to make. It is
// reserved for that single meaning: no command other than `lint` may return it,
// and a lint run that fails partway through exits exitFailure like any other
// runtime failure. Nothing in this binary emits it yet; `lint` itself arrives
// with add-harnaas-lint, and reportError below never produces it.
//
// Termination by signal is not in this list because it is not an exit at all:
// see dieFromSignal, which re-raises the signal and only falls back to
// 128-plus-signal-number where re-raising is unsupported.
const (
	exitSuccess      = 0
	exitFailure      = 1
	exitLintFindings = 2
)

// forceQuitGrace is how long dieFromSignal waits for a re-raised signal to be
// delivered. Delivery ends the process well before this elapses; the wait only
// exists so a platform that silently drops the re-raise still reaches the
// fallback exit instead of hanging.
const forceQuitGrace = 500 * time.Millisecond

func main() {
	// Resolve version and commit before anything reads them — the root command
	// copies Version into its own field as it is built.
	versioninfo.Load()

	os.Exit(run())
}

// run executes the command tree and returns the process exit code. It exists
// as a separate function so the deferred cancel actually runs; main's os.Exit
// would skip it.
func run() int {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Establish the project root once, here, so every command resolves paths
	// against the repository rather than against wherever the user was standing.
	// A failure to find one is carried in the context, not reported: `--version`
	// and `--help` are legitimate outside a repository, and only a command that
	// asks for a root should have to care that there is none.
	ctx = paths.WithDiscoveredRoot(ctx)

	// Diagnostics go to a log file for the rest of the run. Open reports no
	// failure because there is nowhere to report one to: the terminal belongs to
	// the command's own output, and a warning printed there is the interleaving
	// the file exists to avoid. A run whose log could not be opened just has no
	// log.
	closeLog := logging.Open()
	defer closeLog()

	logging.Info(ctx, "harnaas started", slog.String("version", versioninfo.Version))

	watchSignals(cancel, os.Stderr)

	root := cli.NewRootCmd()

	// ExecuteContextC returns the deepest command cobra matched, which is the
	// one whose usage a positional-argument error should show.
	executed, err := root.ExecuteContextC(ctx)
	if err == nil {
		logging.Info(ctx, "harnaas finished", slog.Int("exit_code", exitSuccess))
		return exitSuccess
	}

	if sig := terminatingSignal(err); sig != nil {
		logging.Info(ctx, "harnaas terminated by signal", slog.String("signal", sig.String()))
		cancel()
		dieFromSignal(sig)
	}

	code := reportError(root.ErrOrStderr(), root, executed, err)

	// The failure is recorded by type, never by message. Errors from later
	// phases quote the manifest that produced them, and a team's instructions
	// and rules are the content that must never reach a log file.
	logging.Error(ctx, "harnaas failed",
		slog.Int("exit_code", code),
		slog.String("error_type", fmt.Sprintf("%T", err)),
	)

	return code
}

// watchSignals installs the two-stage handler. The first signal cancels the
// root context so in-flight work unwinds cleanly and prints a notice; because
// signal.Notify has disabled Go's default "signal terminates the process"
// behaviour, a second read is what keeps a further Ctrl-C from being swallowed
// during a slow or stuck shutdown. The caught signal is recorded so the
// eventual termination re-raises that same signal rather than assuming an
// interrupt.
func watchSignals(cancel context.CancelFunc, notice io.Writer) {
	sigChan := make(chan os.Signal, 1)
	signals := []os.Signal{os.Interrupt}
	if runtime.GOOS != "windows" {
		signals = append(signals, syscall.SIGTERM)
	}
	signal.Notify(sigChan, signals...)

	go func() {
		sig := <-sigChan
		procsignal.Store(sig)
		fmt.Fprintln(notice, forceQuitNotice(sig))
		cancel()
		<-sigChan
		dieFromSignal(sig)
	}()
}

// forceQuitNotice is the advisory text for a first signal. It distinguishes an
// interrupt the user typed from a termination signal a supervisor sent, because
// the two want different explanations, and it leads with a blank line so the
// notice does not land on top of a half-written progress line.
func forceQuitNotice(sig os.Signal) string {
	if sig == os.Interrupt {
		return "\nInterrupting… press Ctrl-C again to force quit."
	}
	return "\nReceived termination signal, shutting down… signal again to force quit."
}

// terminatingSignal reports the signal that cancelled the root context, or nil
// if the cancellation was not signal-driven.
//
// The gate is deliberately on a signal having been recorded rather than on the
// error type alone: a context.Canceled that arose without a signal — an
// internally cancelled sub-context, say — is a genuine failure and must be
// reported as one, not dressed up as a user abort that would also wrongly break
// an enclosing shell loop.
func terminatingSignal(err error) os.Signal {
	if !errors.Is(err, context.Canceled) {
		return nil
	}
	return procsignal.Load()
}

// dieFromSignal terminates the process as if it had been killed by sig, rather
// than exiting normally.
//
// The distinction matters to an interactive shell: it aborts a
// `while true; do harnaas …; done` loop only when the child is *killed by*
// SIGINT. A plain exit with status 130 is an ordinary exit, so the loop keeps
// respawning harnaas and the user's Ctrl-C never escapes it. Re-raising the
// actual signal also keeps a SIGTERM shutdown reporting the conventional 143.
//
// The signal is reset to its default disposition, re-raised at this process,
// and given a moment to arrive. Where the re-raise cannot be delivered — on
// Windows, where signal-to-self is unsupported — the conventional
// 128-plus-signal-number exit is the fallback, so the process never hangs.
func dieFromSignal(sig os.Signal) {
	signal.Reset(sig)
	if p, err := os.FindProcess(os.Getpid()); err == nil {
		if err := p.Signal(sig); err == nil {
			time.Sleep(forceQuitGrace)
		}
	}
	os.Exit(exitCodeForSignal(sig))
}

// exitCodeForSignal maps a signal to the conventional 128-plus-signal-number
// exit code — 130 for SIGINT, 143 for SIGTERM — falling back to an interrupt's
// 130 for a signal carrying no numeric value on this platform.
func exitCodeForSignal(sig os.Signal) int {
	if s, ok := sig.(syscall.Signal); ok {
		return 128 + int(s)
	}
	return 128 + int(syscall.SIGINT)
}

// reportError renders err according to the error contract and returns the exit
// code the process should use. It is the single place that decides what a
// failure looks like on the terminal.
//
// root is the command tree's root and executed is the deepest command cobra
// matched; the two differ exactly when a subcommand's own validator failed,
// which is when the subcommand's usage — not the root's — is the useful one.
func reportError(out io.Writer, root, executed *cobra.Command, err error) int {
	var printed *cli.AlreadyPrintedError

	switch {
	case errors.As(err, &printed):
		// The command already wrote a friendly explanation. Printing anything
		// here would restate it in a less useful form.
	case isUnknownCommandOrFlagError(err):
		writeUsageAndError(out, root, err)
	case isPositionalArgError(err):
		writeUsageAndError(out, executed, err)
	default:
		fmt.Fprintln(out, err)
	}

	return exitFailure
}

// isUnknownCommandOrFlagError reports whether err is cobra's complaint about a
// verb or flag it does not recognise, which is a usage problem rather than a
// runtime one.
func isUnknownCommandOrFlagError(err error) bool {
	msg := err.Error()
	return strings.Contains(msg, "unknown command") || strings.Contains(msg, "unknown flag")
}

// isPositionalArgError reports whether err looks like a cobra positional-
// argument validator failure. Cobra's stock validators — ExactArgs, NoArgs,
// MinimumNArgs, MaximumNArgs, RangeArgs — all surface messages containing
// "arg(s)", and that substring appears in none of cobra's other error paths nor
// in harnaas's own errors, so it is a stable discriminator that does not reach
// into cobra internals.
func isPositionalArgError(err error) bool {
	return strings.Contains(err.Error(), "arg(s)")
}

// writeUsageAndError prints the command's usage before the error, so the reader
// sees what was expected and only then what went wrong.
func writeUsageAndError(out io.Writer, cmd *cobra.Command, err error) {
	if cmd == nil {
		fmt.Fprintln(out, err)
		return
	}
	fmt.Fprint(out, cmd.UsageString())
	fmt.Fprintf(out, "\nError: invalid usage: %v\n", err)
}

package cli

import (
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"os"

	"github.com/spf13/cobra"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/interactive"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/jsonutil"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/logging"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/paths"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/uiform"
)

const initLong = `Create harnaas.json at the project root, declaring which harnesses this
project targets.

init writes that one file and nothing else. The harness directories, the
.harnaas directory and any ignore-file entries belong to harnaas install,
which records what it created; anything init created would be unmanaged, and
the next install would report a conflict against init's own output.

The harnesses a project already uses are detected from what is in the
repository and pre-filled. Pass --harness to name them yourself instead.`

// manifestPerm is the mode a scaffolded manifest is created with: a committed,
// hand-edited file, so the ordinary non-executable default.
const manifestPerm fs.FileMode = 0o644

// initOptions holds the flags `harnaas init` accepts. Each is registered
// locally on the command, because the root carries no persistent flags.
type initOptions struct {
	// force allows replacing an existing manifest.
	force bool

	// assumeYes accepts the pre-filled selection without prompting, so a user
	// on a terminal can take the non-interactive path deliberately.
	assumeYes bool

	// harnesses is the raw flag input, unvalidated: the strings the user typed,
	// so a name the roster rejects can be quoted back as written.
	harnesses []string
}

// newInitCmd builds `harnaas init`.
func newInitCmd() *cobra.Command {
	opts := &initOptions{}

	cmd := &cobra.Command{
		Use:   "init",
		Short: "Create harnaas.json for this project",
		Long:  initLong,
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runInit(cmd, opts)
		},
	}

	flags := cmd.Flags()
	flags.BoolVar(&opts.force, "force", false,
		"replace an existing "+manifest.FileName)
	flags.BoolVarP(&opts.assumeYes, "yes", "y", false,
		"accept the harness selection without prompting")
	// A repeated flag rather than a comma-separated list: a harness id is one
	// token, and splitting on commas would turn `--harness "a, b"` into a name
	// with a leading space and a diagnostic about whitespace nobody typed
	// deliberately.
	flags.StringArrayVar(&opts.harnesses, "harness", nil,
		"harness to target; repeat for each one, overriding detection")

	return cmd
}

// runInit scaffolds the manifest.
//
// The order of the steps is the contract: everything that can refuse happens
// before anything is written, and before the prompt too — asking a question
// whose answer cannot change the outcome wastes the one moment the user is
// paying attention.
func runInit(cmd *cobra.Command, opts *initOptions) error {
	ctx := cmd.Context()

	root, err := paths.ProjectRoot(ctx)
	if err != nil {
		return err
	}
	path, err := manifest.Path(ctx)
	if err != nil {
		return err
	}

	selection, err := selectHarnesses(root, opts.harnesses)
	if err != nil {
		return err
	}
	if err := refuseExistingManifest(path, opts.force); err != nil {
		return err
	}

	explainSelection(cmd, selection)

	confirmed, err := confirmSelection(cmd, selection, opts.assumeYes)
	if err != nil {
		return err
	}
	if !confirmed {
		// A decline is an answer, not a failure: the user was asked and said
		// no, and harnaas did exactly that. Only a cancelled prompt — the user
		// walking away from a question they never chose to answer — exits
		// non-zero.
		advisef(cmd, "Nothing was created. Re-run with --harness to name the harnesses yourself.\n")
		return nil
	}

	if err := writeScaffold(path, selection.Harnesses); err != nil {
		return err
	}

	logging.Info(ctx, "manifest created",
		slog.String("path", path),
		slog.Int("harness_count", len(selection.Harnesses)),
	)
	reportCreated(cmd, path)

	return nil
}

// scaffold is the manifest init writes.
//
// It is a type of its own rather than [manifest.Document] because the two answer
// different questions: Document is what decoding produces and carries fields
// that are not part of the file, while this is the file. The field order here is
// the order they appear in the written manifest, which is the order a person
// reads them in — what this targets, where content comes from, what is wanted.
type scaffold struct {
	Version   int                `json:"version"`
	Harnesses []harness.ID       `json:"harnesses"`
	Sources   map[string]string  `json:"sources"`
	Assets    []assetPlaceholder `json:"assets"`
}

// assetPlaceholder is the element type of an empty `assets` array. The array is
// always empty here — init declares no assets, because it has nothing to declare
// them from — so the type exists only to keep the field from being `any`.
type assetPlaceholder struct{}

// newScaffold builds the document for the selected harnesses.
//
// `sources` and `assets` are empty rather than absent, and non-nil rather than
// nil, so the written file shows the author both fields with the shape their
// content goes in. A manifest that omitted them would decode identically and
// teach nothing.
func newScaffold(harnesses []harness.ID) scaffold {
	return scaffold{
		Version:   manifest.SupportedVersion,
		Harnesses: harnesses,
		Sources:   map[string]string{},
		Assets:    []assetPlaceholder{},
	}
}

// writeScaffold encodes the manifest and puts it on disk in one step.
//
// The write goes through jsonutil so the file is staged, synced and renamed into
// place: a forced run over an existing manifest either replaces it completely or
// leaves the previous one intact, and never leaves a staging file behind. The
// document is encoded fully before the write starts, so an unencodable value
// fails with nothing touched.
func writeScaffold(path string, harnesses []harness.ID) error {
	document, err := jsonutil.Marshal(newScaffold(harnesses))
	if err != nil {
		return fmt.Errorf("encode %s: %w", manifest.FileName, err)
	}
	if err := jsonutil.WriteFileAtomic(path, document, manifestPerm); err != nil {
		return fmt.Errorf("write %s: %w", manifest.FileName, err)
	}
	return nil
}

// manifestExistsError refuses to replace a manifest that is already there.
//
// The manifest is the file a team reviews, and init is the one command allowed
// to write it. Replacing one silently would discard declarations nobody asked
// harnaas to touch, so the refusal is the default and the flag that lifts it is
// named in the message.
type manifestExistsError struct {
	// Path is the manifest left untouched.
	Path string
}

func (e *manifestExistsError) Error() string {
	return fmt.Sprintf(
		"a manifest already exists at %s\n\n"+
			"Edit it directly, or re-run with --force to replace it with a fresh one.",
		e.Path,
	)
}

// refuseExistingManifest checks for a manifest already at the project root.
//
// A stat that fails for any reason other than "not there" is treated as "not
// there" deliberately: the write is the authority on whether the file can be
// replaced, and guessing from a failed stat would refuse a run that would have
// succeeded, with a message about a file harnaas could not even see.
func refuseExistingManifest(path string, force bool) error {
	if force {
		return nil
	}
	if _, err := os.Lstat(path); err == nil {
		return &manifestExistsError{Path: path}
	}
	return nil
}

// explainSelection says where the selection came from, on stderr, before the
// user is asked to confirm it.
//
// A flag-supplied selection gets no sentence: the user typed it a moment ago,
// and repeating it back is noise. The other two are worth stating — detection
// can be wrong in both directions, and the default is the one case where harnaas
// picked a harness the project shows no sign of using.
func explainSelection(cmd *cobra.Command, selection harnessSelection) {
	switch selection.Origin {
	case originFlag:
		// Nothing to say: the selection is the user's own words.
	case originDetected:
		advisef(cmd, "Detected %s in this project.\n", displayNames(selection.Harnesses))
	case originDefault:
		advisef(cmd, "No supported harness detected in this project; targeting %s.\n",
			displayNames(selection.Harnesses))
	}
}

// confirmSelection asks the user to confirm the selection, where asking is
// possible and was not waived.
//
// Not asking is the normal case, not a degraded one: a run with no terminal, a
// run inside a coding agent and a run with --yes all proceed from the detected
// and flag-supplied values, because every workflow here has to be completable
// without a prompt. The prompt renders on stderr so a confirmed run's stdout
// still carries the result alone.
func confirmSelection(cmd *cobra.Command, selection harnessSelection, assumeYes bool) (bool, error) {
	in, out := cmd.InOrStdin(), cmd.ErrOrStderr()
	if assumeYes || !interactive.CanPrompt(in, out) {
		return true, nil
	}

	question := fmt.Sprintf("Create %s targeting %s?",
		manifest.FileName, displayNames(selection.Harnesses))

	confirmed, err := uiform.Confirm(cmd.Context(), in, out, question, true)
	if errors.Is(err, uiform.ErrCancelled) {
		// Cancelling is not declining. The user answered nothing, so harnaas
		// does nothing and says so with a non-zero exit, rather than taking the
		// default answer on behalf of someone who walked away.
		return false, fmt.Errorf("%w: no %s was created", err, manifest.FileName)
	}
	if err != nil {
		return false, fmt.Errorf("confirm harness selection: %w", err)
	}

	return confirmed, nil
}

// reportCreated prints what init did and what to do next, on stdout.
//
// The remaining setup is described rather than performed, and the description
// names the command that performs it. There is deliberately no flag that makes
// init do any of it.
func reportCreated(cmd *cobra.Command, path string) {
	out := cmd.OutOrStdout()
	fmt.Fprintf(out, "Created %s\n", path)
	fmt.Fprintf(out, "\nNext: declare the assets you want in %s, then run `harnaas install`.\n",
		manifest.FileName)
	fmt.Fprintf(out, "`harnaas install` creates %s/, writes into the harness directories and\n",
		manifest.LocalRoot)
	fmt.Fprint(out, "maintains the ignore-file entries for what it installed. init wrote none of them.\n")
}

